  _o.CDELT1 = this.CDELT1();
  _o.CDELT2 = this.CDELT2();
  _o.CROTA2 = this.CROTA2();
  _o.PC = this.bb!.createScalarList<number>(this.PC.bind(this), this.pcLength());
  _o.RSUN_OBS_ARCSEC = this.RSUN_OBS_ARCSEC();
  _o.RSUN_REF_M = this.RSUN_REF_M();
  _o.DSUN_OBS_M = this.DSUN_OBS_M();
