export class SDIT implements flatbuffers.IGeneratedObject {
constructor(
  public OBSERVATORY: string|Uint8Array|null = null,
  public INSTRUMENT: string|Uint8Array|null = null,
  public MEASUREMENT: string|Uint8Array|null = null,
  public WAVELENGTH_NM: number = NaN,
  public IMAGE_ID: string|Uint8Array|null = null,
  public REQUESTED_AT: string|Uint8Array|null = null,
  public OBSERVED_AT: string|Uint8Array|null = null,
  public DATE_OBS: string|Uint8Array|null = null,
  public TIME_SCALE: string|Uint8Array|null = null,
  public CADENCE_S: number = NaN,
  public EXPOSURE_S: number = NaN,
  public IMAGE_CID: string|Uint8Array|null = null,
  public IMAGE_MEDIA_TYPE: string|Uint8Array|null = null,
  public IMAGE_DIGEST: string|Uint8Array|null = null,
  public IMAGE_SIZE_BYTES: bigint = BigInt('0'),
  public HEADER_CID: string|Uint8Array|null = null,
  public WIDTH: number = 0,
  public HEIGHT: number = 0,
  public CTYPE1: string|Uint8Array|null = null,
  public CTYPE2: string|Uint8Array|null = null,
  public CUNIT1: string|Uint8Array|null = null,
  public CUNIT2: string|Uint8Array|null = null,
  public CRPIX1: number = NaN,
  public CRPIX2: number = NaN,
  public CRVAL1: number = NaN,
  public CRVAL2: number = NaN,
  public CDELT1: number = NaN,
  public CDELT2: number = NaN,
  public CROTA2: number = NaN,
  public PC: (number)[] = [],
  public RSUN_OBS_ARCSEC: number = NaN,
  public RSUN_REF_M: number = NaN,
  public DSUN_OBS_M: number = NaN,
  public CRLN_OBS_DEG: number = NaN,
  public CRLT_OBS_DEG: number = NaN,
  public HGLN_OBS_DEG: number = NaN,
  public HGLT_OBS_DEG: number = NaN,
  public QUALITY: bigint = BigInt('0'),
  public HAS_QUALITY: boolean = false,
  public PROCESSING: string|Uint8Array|null = null,
  public PROVENANCE: PVNT|null = null,
  public SOURCE_CID: string|Uint8Array|null = null,
  public SOURCE_DIGEST: string|Uint8Array|null = null,
  public RETRIEVED_AT: string|Uint8Array|null = null
){}


pack(builder:flatbuffers.Builder): flatbuffers.Offset {
  const OBSERVATORY = (this.OBSERVATORY !== null ? builder.createString(this.OBSERVATORY!) : 0);
  const INSTRUMENT = (this.INSTRUMENT !== null ? builder.createString(this.INSTRUMENT!) : 0);
  const MEASUREMENT = (this.MEASUREMENT !== null ? builder.createString(this.MEASUREMENT!) : 0);
  const IMAGE_ID = (this.IMAGE_ID !== null ? builder.createString(this.IMAGE_ID!) : 0);
  const REQUESTED_AT = (this.REQUESTED_AT !== null ? builder.createString(this.REQUESTED_AT!) : 0);
  const OBSERVED_AT = (this.OBSERVED_AT !== null ? builder.createString(this.OBSERVED_AT!) : 0);
  const DATE_OBS = (this.DATE_OBS !== null ? builder.createString(this.DATE_OBS!) : 0);
  const TIME_SCALE = (this.TIME_SCALE !== null ? builder.createString(this.TIME_SCALE!) : 0);
  const IMAGE_CID = (this.IMAGE_CID !== null ? builder.createString(this.IMAGE_CID!) : 0);
  const IMAGE_MEDIA_TYPE = (this.IMAGE_MEDIA_TYPE !== null ? builder.createString(this.IMAGE_MEDIA_TYPE!) : 0);
  const IMAGE_DIGEST = (this.IMAGE_DIGEST !== null ? builder.createString(this.IMAGE_DIGEST!) : 0);
  const HEADER_CID = (this.HEADER_CID !== null ? builder.createString(this.HEADER_CID!) : 0);
  const CTYPE1 = (this.CTYPE1 !== null ? builder.createString(this.CTYPE1!) : 0);
  const CTYPE2 = (this.CTYPE2 !== null ? builder.createString(this.CTYPE2!) : 0);
  const CUNIT1 = (this.CUNIT1 !== null ? builder.createString(this.CUNIT1!) : 0);
  const CUNIT2 = (this.CUNIT2 !== null ? builder.createString(this.CUNIT2!) : 0);
  const PC = SDI.createPcVector(builder, this.PC);
  const PROCESSING = (this.PROCESSING !== null ? builder.createString(this.PROCESSING!) : 0);
  const PROVENANCE = (this.PROVENANCE !== null ? this.PROVENANCE!.pack(builder) : 0);
  const SOURCE_CID = (this.SOURCE_CID !== null ? builder.createString(this.SOURCE_CID!) : 0);
  const SOURCE_DIGEST = (this.SOURCE_DIGEST !== null ? builder.createString(this.SOURCE_DIGEST!) : 0);
  const RETRIEVED_AT = (this.RETRIEVED_AT !== null ? builder.createString(this.RETRIEVED_AT!) : 0);

  SDI.startSDI(builder);
  SDI.addObservatory(builder, OBSERVATORY);
  SDI.addInstrument(builder, INSTRUMENT);
  SDI.addMeasurement(builder, MEASUREMENT);
  SDI.addWavelengthNm(builder, this.WAVELENGTH_NM);
  SDI.addImageId(builder, IMAGE_ID);
  SDI.addRequestedAt(builder, REQUESTED_AT);
  SDI.addObservedAt(builder, OBSERVED_AT);
  SDI.addDateObs(builder, DATE_OBS);
  SDI.addTimeScale(builder, TIME_SCALE);
  SDI.addCadenceS(builder, this.CADENCE_S);
  SDI.addExposureS(builder, this.EXPOSURE_S);
  SDI.addImageCid(builder, IMAGE_CID);
  SDI.addImageMediaType(builder, IMAGE_MEDIA_TYPE);
  SDI.addImageDigest(builder, IMAGE_DIGEST);
  SDI.addImageSizeBytes(builder, this.IMAGE_SIZE_BYTES);
  SDI.addHeaderCid(builder, HEADER_CID);
  SDI.addWidth(builder, this.WIDTH);
  SDI.addHeight(builder, this.HEIGHT);
  SDI.addCtype1(builder, CTYPE1);
  SDI.addCtype2(builder, CTYPE2);
  SDI.addCunit1(builder, CUNIT1);
  SDI.addCunit2(builder, CUNIT2);
  SDI.addCrpix1(builder, this.CRPIX1);
  SDI.addCrpix2(builder, this.CRPIX2);
  SDI.addCrval1(builder, this.CRVAL1);
  SDI.addCrval2(builder, this.CRVAL2);
  SDI.addCdelt1(builder, this.CDELT1);
  SDI.addCdelt2(builder, this.CDELT2);
  SDI.addCrota2(builder, this.CROTA2);
  SDI.addPc(builder, PC);
  SDI.addRsunObsArcsec(builder, this.RSUN_OBS_ARCSEC);
  SDI.addRsunRefM(builder, this.RSUN_REF_M);
  SDI.addDsunObsM(builder, this.DSUN_OBS_M);
  SDI.addCrlnObsDeg(builder, this.CRLN_OBS_DEG);
  SDI.addCrltObsDeg(builder, this.CRLT_OBS_DEG);
  SDI.addHglnObsDeg(builder, this.HGLN_OBS_DEG);
  SDI.addHgltObsDeg(builder, this.HGLT_OBS_DEG);
  SDI.addQuality(builder, this.QUALITY);
  SDI.addHasQuality(builder, this.HAS_QUALITY);
  SDI.addProcessing(builder, PROCESSING);
  SDI.addProvenance(builder, PROVENANCE);
  SDI.addSourceCid(builder, SOURCE_CID);
  SDI.addSourceDigest(builder, SOURCE_DIGEST);
  SDI.addRetrievedAt(builder, RETRIEVED_AT);

  return SDI.endSDI(builder);
}
}
